content.arguments:
{"command": "$before=(Get-ChildItem "$env:LOCALAPPDATA\Temp" -Force -Recurse -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
Get-ChildItem "$env:LOCALAPPDATA\Temp" -Force -ErrorAction SilentlyContinue | ForEach-Object { try { Remove-Item $_.FullName -Recurse -Force -ErrorAction Stop } catch {} }
Get-ChildItem 'C:\Windows\Temp' -Force -ErrorAction SilentlyContinue | ForEach-Object { try { Remove-Item $_.FullName -Recurse -Force -ErrorAction Stop } catch {} }
$after=(Get-ChildItem "$env:LOCALAPPDATA\Temp" -Force -Recurse -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
"释放 {0:N2} GB；Temp 现在 {1:N2} GB" -f (($before-$after)/1GB), ($after/1GB)
$d=Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='C:'"; "C 盘剩 {0:N1} GB ({1:N0}%)" -f ($d.FreeSpace/1GB), ($d.FreeSpace/$d.Size*100)", "description": "Clear temp folders and report freed space", "timeoutMs": 180000}

